import{_ as t,o,c as n,a2 as s}from"./chunks/framework.CHeM0PsO.js";const u=JSON.parse('{"title":"Connector Store & SDK","description":"","frontmatter":{"epic":5,"title":"Connector Store & SDK","status":"⏳ In Progress — 5.1, 5.2, 5.4, 5.5 done; 5.3 partially done (free + token-auth examples shipped, Tier 2 script and paid examples blocked on 5.6/epic 6); 5.6 still 📋 Planned","scope":"shared","sourceUrl":"https://github.com/sovereignfs/sovereign-edge/blob/main/docs/epics/shared/connector-store-sdk.md"},"headers":[],"relativePath":"sovereign-edge/epics/shared/connector-store-sdk.md","filePath":"sovereign-edge/epics/shared/connector-store-sdk.md"}'),i={name:"sovereign-edge/epics/shared/connector-store-sdk.md"};function r(a,e,c,l,d,p){return o(),n("div",null,[...e[0]||(e[0]=[s('<h1 id="epic-connector-store-sdk" tabindex="-1">Epic: Connector Store &amp; SDK <a class="header-anchor" href="#epic-connector-store-sdk" aria-label="Permalink to &quot;Epic: Connector Store &amp; SDK&quot;">​</a></h1><blockquote><p>Phase 3 — opening the connector layer to third-party developers: SDK, plugin template, examples, public registry, and the in-app store.</p></blockquote><p><strong>Scope note:</strong> platform-neutral by design, not implemented inside one app first — see the taxonomy note in <a href="./../README.html#layout">docs/epics/README.md</a>.</p><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>Mirrors <code>sovereign</code>&#39;s own plugin-development trio (<code>sovereign-plugin-template</code></p><ul><li><code>sovereign-plugins-examples</code> + the public plugin registry), adapted for connectors instead of Next.js modules. This is deliberately the <strong>last</strong> phase — everything here builds on the <a href="./../mobile/connector-framework.html">Connector Framework</a> unchanged, per research 0001&#39;s &quot;build once, widen without rework&quot; principle.</li></ul><h2 id="tasks" tabindex="-1">Tasks <a class="header-anchor" href="#tasks" aria-label="Permalink to &quot;Tasks&quot;">​</a></h2><h4 id="✅-5-1-—-connector-sdk" tabindex="-1">✅ 5.1 — Connector SDK <a class="header-anchor" href="#✅-5-1-—-connector-sdk" aria-label="Permalink to &quot;✅ 5.1 — Connector SDK&quot;">​</a></h4><p><strong>Goal:</strong> A published package with the manifest schema types and a validator, for connector authors to build and test against before submission.</p><p><strong>Deliverables:</strong></p><ul><li>Zero-dependency package (mirrors <code>@sovereignfs/sdk</code>&#39;s own zero-dep constraint) exporting the Tier 1/Tier 2 manifest types and a validator function.</li><li>Versioned independently, with the same &quot;no breaking changes in a patch&quot; discipline <code>sovereign</code>&#39;s SDK follows once this is a public contract.</li></ul><p><strong>Dependencies:</strong> Connector Framework epic (2.1) — reuses its schema directly, does not redefine it.</p><p><strong>Review checklist:</strong></p><ul><li>The SDK&#39;s validator accepts the exact same manifests the app&#39;s own runtime (epic 2.4) already accepts — no drift between author-time and load-time validation.</li></ul><p><strong>Decided:</strong></p><ul><li>New package <code>packages/connector-sdk</code> (<code>@sovereignfs/connector-sdk</code>, <code>0.1.0</code>), structurally mirroring <code>sovereign</code>&#39;s real <code>@sovereignfs/sdk</code><code>package.json</code> (dual <code>exports</code>: raw <code>src/*.ts</code> for workspace consumers, <code>publishConfig.exports</code> pointing at built <code>dist/*.js</code>+<code>.d.ts</code> for real npm consumers).</li><li>The manifest schema (<code>src/schema.ts</code>), validator (<code>src/validate.ts</code>), fixtures, and test suite were <strong>relocated</strong>, not duplicated, from <code>apps/mobile/src/connectors/manifest/</code> — <code>apps/mobile</code> now consumes the package via <code>workspace:*</code> across all 8 of its former import sites. This is what makes the review checklist true by construction: it&#39;s the same code running in both places, not a second implementation that could drift.</li><li><code>packages/core</code> was deliberately <strong>not</strong> the home for this — its README earmarked the schema for future extraction, but that package also covers genuinely internal-only concerns (permission state machine, routing, adapter interfaces) a third-party connector author has no business depending on. <code>packages/connector-sdk</code>&#39;s README documents its own scope and the Tier-1/Tier-3 status honestly.</li></ul><p><strong>Honest gaps:</strong></p><ul><li><strong>&quot;Tier 1/Tier 2 manifest types&quot; (this task&#39;s own original deliverable text) is not what shipped.</strong> Tier 2 has no schema anywhere yet — its sandboxed script runtime (task 5.6) hasn&#39;t been designed. The SDK exports what the runtime actually accepts today: Tier 1 and Tier 3 (the real <code>connectorManifest</code> discriminated union). Tier 2 types will be added here once 5.6 gives them a real shape.</li><li><strong>Not actually published to npm.</strong> The package is built and verified publish-ready (<code>pnpm --filter @sovereignfs/connector-sdk build</code> produces a real <code>dist/index.js</code> + <code>dist/index.d.ts</code>; <code>publishConfig</code> is set), but the <code>npm publish</code> step itself was not performed — no npm account/org credentials exist in this environment, and it&#39;s an irreversible public action regardless of packaging readiness. That&#39;s a follow-up for whoever holds the project&#39;s npm access.</li></ul><p><strong>Verified:</strong></p><ul><li><code>pnpm --filter @sovereignfs/connector-sdk typecheck</code> / <code>test</code> (18 tests, the relocated <code>validate.test.ts</code> suite, now running under Vitest instead of mobile&#39;s Jest) / <code>build</code> all pass.</li><li><code>pnpm --filter mobile typecheck</code> / <code>lint</code> / <code>test</code> (223 tests, full suite) all pass unchanged after the import rewrite.</li><li><code>pnpm check:offline</code> (root) stays clean — the offline-boundary walk never reached into <code>connectors/</code> in the first place, and importing from an external workspace package doesn&#39;t change that.</li></ul><hr><h4 id="✅-5-2-—-connector-plugin-template" tabindex="-1">✅ 5.2 — Connector plugin template <a class="header-anchor" href="#✅-5-2-—-connector-plugin-template" aria-label="Permalink to &quot;✅ 5.2 — Connector plugin template&quot;">​</a></h4><p><strong>Goal:</strong> A &quot;use this template&quot; starting point for a new third-party connector.</p><p><strong>Deliverables:</strong></p><ul><li>Template repo: example manifest, README explaining the tiers and submission process, optional Tier 2 script skeleton.</li></ul><p><strong>Dependencies:</strong> Task 5.1.</p><p><strong>Review checklist:</strong></p><ul><li>A developer unfamiliar with the project can go from cloning the template to a submittable connector manifest without reading source code.</li></ul><p><strong>Decided:</strong></p><ul><li><code>templates/connector-plugin-template/</code> <strong>inside this repo</strong>, not a separate GitHub repo. <code>sovereign</code>&#39;s own equivalent (<code>sovereign-plugin-template</code>) is a standalone repo, but creating a new public repo is a real, visible action outside what an assistant should do without the project owner confirming the exact name and visibility first — that&#39;s a decision left to a human. The in-repo template can be split out into its own repo later with no loss; nothing about its content assumes it lives here.</li><li>The example manifest (<code>manifest.json</code>, a fictional weather-lookup connector) is a genuine, complete Tier 1 example — not an abbreviated sketch — and <code>validate.mjs</code> runs it through the actual <code>@sovereignfs/connector-sdk</code> validator, so <code>npm run validate</code> in the template shows a connector author exactly what the app&#39;s own load-time check would say.</li><li>The README states plainly which tier is actually usable: <strong>Tier 1 only.</strong> Tier 3 is first-party-only by design (a manifest alone can&#39;t authorize native code, since Tier 3 dispatches to a handler already registered inside the app). Tier 2 has no runtime yet (task 5.6) — its <code>tier2-preview/</code> directory is explicitly marked non-functional in its own README and in a comment at the top of its one script file, so it can&#39;t be mistaken for a working example.</li></ul><p><strong>Honest gap:</strong></p><ul><li>The README&#39;s &quot;Submission&quot; section says outright that there is no public registry or submission process yet (task 5.4, still 📋). A connector built from this template can be validated and run locally, but has nowhere to be submitted to yet.</li></ul><p><strong>Verified:</strong></p><ul><li>Confirmed <code>manifest.json</code> actually validates against the real built <code>@sovereignfs/connector-sdk</code> (<code>dist/index.js</code>), not just a plausible-looking JSON file: <code>validateManifest()</code> returns <code>{ valid: true, ... }</code>.</li><li>Confirmed the validator is not a rubber stamp: mutating the same manifest to smuggle a credential into a URL query value (exactly the rule the README calls out) makes <code>validateManifest()</code> return <code>{ valid: false, issues: [...] }</code> with the expected message.</li></ul><hr><h4 id="⏳-5-3-—-first-party-example-connectors-in-progress-—-free-token-auth-done" tabindex="-1">⏳ 5.3 — First-party example connectors (in progress — free + token-auth done) <a class="header-anchor" href="#⏳-5-3-—-first-party-example-connectors-in-progress-—-free-token-auth-done" aria-label="Permalink to &quot;⏳ 5.3 — First-party example connectors (in progress — free + token-auth done)&quot;">​</a></h4><p><strong>Goal:</strong> A reference set demonstrating the range of what a connector can be, mirroring <code>sovereign-plugins-examples</code>.</p><p><strong>Deliverables:</strong></p><ul><li>A simple Tier 1 REST connector, one with token auth, one Tier 2 connector with a transform script, one demonstrating the paid/entitlement flow (epic 6).</li></ul><p><strong>Dependencies:</strong> Task 5.1, Task 6 (monetization, for the paid example).</p><p><strong>Review checklist:</strong></p><ul><li>Each example validates against the SDK and installs/runs in the app unmodified.</li></ul><p><strong>Decided:</strong></p><ul><li><code>examples/connectors/</code> in-repo (same reasoning as 5.2&#39;s template: a separate <code>sovereign-plugins-examples</code>-style repo is a real, visible action left for the project owner, not something to create unprompted).</li><li>Two of the four deliverables shipped now: <code>simple-rest-open-meteo/</code> (no credentials — every value comes from the model&#39;s own tool arguments) and <code>token-auth-github/</code> (a stored credential injected into a request header). Both call real, recognizable public APIs (Open-Meteo&#39;s free weather API; GitHub&#39;s <code>GET /user</code>) rather than fabricated endpoints, so the manifests read as genuine examples, not placeholders.</li><li><strong>&quot;Installs/runs in the app unmodified&quot;</strong> doesn&#39;t have a literal path to exercise yet: neither app has a generic &quot;install an arbitrary manifest&quot; feature (that&#39;s task 5.5, the in-app store, itself blocked on 5.4&#39;s registry) — both apps&#39; own connector lists are still hardcoded to the first-party Search connector (mobile: <code>installedConnectors()</code> in <code>apps/mobile/src/settings/ModelSessionProvider.tsx</code>; desktop: <code>known_connector_manifests()</code> in <code>apps/desktop/src-tauri/src/lib.rs</code>). Read literally, the checklist can&#39;t be satisfied by either app today, for any connector. Read for what it&#39;s actually checking — that a manifest runs through the real, connector-agnostic runtime code unmodified, not a special-cased reimplementation — it&#39;s provable now: <code>apps/mobile/src/connectors/runtime/examples.smoke.test.ts</code> calls the same <code>executeConnectorCall</code> the app itself calls, against a real local TCP listener (mirroring the Rust side&#39;s own real-socket test in <code>apps/desktop/src-tauri/src/connectors/orchestration.rs</code>), not a mocked <code>fetch</code>.</li></ul><p><strong>Honest gaps:</strong></p><ul><li>The Tier 2 transform-script example and the paid/entitlement example remain undone, blocked on task 5.6 (no sandboxed runtime exists) and epic 6 (monetization) respectively — the user explicitly asked to skip the paid example and do only the free/token-auth pair for now.</li><li>The token-auth example surfaces a real schema constraint worth stating plainly: manifests have no string interpolation, so a stored credential must already be the complete header value (e.g. <code>Bearer &lt;token&gt;</code>) — a connector can&#39;t declare a prefix. Documented in the example&#39;s own README rather than hidden.</li></ul><p><strong>Verified:</strong></p><ul><li>Both example manifests pass <code>validateManifest()</code> from the real, installed <code>@sovereignfs/connector-sdk</code>.</li><li><code>apps/mobile/src/connectors/runtime/examples.smoke.test.ts</code>: both examples pass through <code>executeConnectorCall</code> against a real loopback HTTP server (no mocked <code>fetch</code>) — the free example&#39;s slot-filled query parameters reach the server correctly, and the token-auth example&#39;s <code>Authorization</code> header carries the exact credential value read from the (mocked) vault, proving the credential-injection path works end to end.</li><li><code>pnpm --filter mobile typecheck</code> / <code>lint</code> / <code>test</code> (225 tests, full suite, up from 223 — the two new smoke tests) all pass.</li><li><code>pnpm check:offline</code> (root) stays clean.</li></ul><hr><h4 id="✅-5-4-—-public-connector-registry-and-submission-process" tabindex="-1">✅ 5.4 — Public connector registry and submission process <a class="header-anchor" href="#✅-5-4-—-public-connector-registry-and-submission-process" aria-label="Permalink to &quot;✅ 5.4 — Public connector registry and submission process&quot;">​</a></h4><p><strong>Goal:</strong> A reviewable, public index of connectors third parties can submit to.</p><p><strong>Deliverables:</strong></p><ul><li>A JSON index (mirrors <code>sovereign</code>&#39;s <code>registry/plugins.json</code> pattern) plus a submission process (PR-based or a form).</li><li>Review checklist for submissions: declared network domain matches what the manifest actually calls, pricing is declared honestly, tool schema is sane. Lighter review burden than native-code review, since Tier 1/2 connectors ship no arbitrary executable code.</li></ul><p><strong>Dependencies:</strong> Task 5.1.</p><p><strong>Review checklist:</strong></p><ul><li>A submitted connector manifest that lies about its declared network domain is caught by the review process before publication.</li></ul><p><strong>Decided:</strong></p><ul><li><code>registry/connectors.json</code> — a real deviation from <code>sovereign</code>&#39;s own <code>registry/plugins.json</code> pattern, made deliberately: <code>sovereign</code> plugin entries point at external git repositories shipping real code, so validating one means cloning the source, checking its manifest/LICENSE, and pinning a content hash against later drift. A Tier 1/2 connector has no code at all — &quot;no connector-specific code exists in the runtime; a manifest is the whole of a Tier 1 connector&quot; (the Connector Framework epic&#39;s own words). So a registry entry here <strong>embeds the manifest directly</strong> (<code>{ id, submittedBy, manifest }</code>) instead of pointing at one. There&#39;s nothing external to fetch and nothing that can drift after review — the manifest in the PR diff is exactly what ships — so no content-hash provenance step exists here; <code>registry/CONTRIBUTING.md</code> explains why, explicitly, rather than silently doing less than the pattern it mirrors.</li><li><strong>The network-domain-lying check is not a manual review step — it&#39;s structural</strong>, and already existed before this task: <code>validateManifest</code> (task 2.1/5.1, unchanged) already rejects a manifest whose <code>request.origin</code> isn&#39;t a member of its own declared <code>permissions.network.origins</code>. <code>registry/validate.mjs</code> calls that exact function against every entry&#39;s embedded manifest, so the review checklist&#39;s own example is satisfied by construction, not by a reviewer&#39;s judgment call.</li><li>Pricing-honesty and tool-schema-sanity are <strong>not</strong> machine-checkable from the manifest alone (the schema requires <em>a</em> <code>pricing</code> value, not a true one) — <code>registry/CONTRIBUTING.md</code> and the new <code>.github/PULL_REQUEST_TEMPLATE/registry-submission.md</code> say so plainly, rather than implying automated validation covers more than it does.</li><li>The registry starts genuinely empty (<code>&quot;connectors&quot;: []</code>) rather than seeded with the task 5.3 example connectors — those are documentation examples (<code>com.example.*</code> ids), not real submissions, and mixing placeholder entries into a &quot;public, reviewable index&quot; would misrepresent what&#39;s actually been submitted and reviewed. Nothing has, yet.</li><li>Wired into CI (<code>.github/workflows/ci.yml</code>, <code>pnpm registry:check</code>) rather than left as a local-only script — a submission&#39;s validity is checked on every PR touching it, the same as every other correctness gate in this repo.</li></ul><p><strong>Honest gap:</strong></p><ul><li>The registry has no consumer. Neither app has a &quot;browse/install from the registry&quot; feature yet — that&#39;s task 5.5, itself blocked on this task, still 📋 Planned. A merged entry here is real (reviewed, validated, version-controlled) but nothing reads from it yet. Stated explicitly in <code>registry/CONTRIBUTING.md</code>&#39;s own &quot;Status&quot; section.</li></ul><p><strong>Verified:</strong></p><ul><li><code>pnpm registry:validate</code> (builds <code>@sovereignfs/connector-sdk</code>, then validates the real committed <code>registry/connectors.json</code>) passes.</li><li><code>pnpm registry:test</code> (<code>node --test</code>, no external test framework needed for a script this small): 7 real assertions, including — the one that matters most for this task&#39;s review checklist — a manifest whose <code>request.origin</code> doesn&#39;t match its declared <code>permissions.network.origins</code> is rejected with an explicit <code>permissions.network.origins</code> error, proving the &quot;lying about its network domain&quot; case is actually caught, not just assumed to be.</li><li><code>pnpm lint</code> / <code>pnpm typecheck</code> / <code>pnpm check:offline</code> (root, all workspace packages) stay clean.</li><li><code>.github/workflows/ci.yml</code>&#39;s new step and YAML syntax verified valid.</li></ul><hr><h4 id="✅-5-5-—-in-app-connector-store" tabindex="-1">✅ 5.5 — In-app Connector Store <a class="header-anchor" href="#✅-5-5-—-in-app-connector-store" aria-label="Permalink to &quot;✅ 5.5 — In-app Connector Store&quot;">​</a></h4><p><strong>Goal:</strong> The end-user-facing browse/install surface.</p><p><strong>Deliverables:</strong></p><ul><li>Browse, search, install, and manage connectors from the registry, inside the app.</li><li>Per-connector permission grant happens at install time, reusing epic 2.2&#39;s consent model unchanged.</li></ul><p><strong>Dependencies:</strong> Task 5.4, Connector Framework epic (2.2).</p><p><strong>Review checklist:</strong></p><ul><li>Installing a third-party connector from the store goes through the exact same permission-grant flow as the first-party Search/Sovereign Tasks connectors — no separate, weaker path for third-party connectors.</li></ul><p><strong>Decided:</strong></p><ul><li><strong>Live registry fetch</strong>, not a build-time snapshot — the first network access in either app that isn&#39;t a specific granted connector&#39;s own request. Explicit, user-facing about that: both store screens state plainly that this one screen reaches the internet for its own sake, rather than fetching silently the way every other screen in either app never does. Mobile reuses <code>allowNetworkForConnector</code> (already a generic &quot;network access from <code>src/connectors/</code>&quot; door, not connector-execution- specific); desktop reuses <code>AppState</code>&#39;s existing <code>connector_http_client</code> and wraps only the request <code>.send()</code> in <code>net_guard::allow_network</code>, mirroring <code>execute.rs</code>&#39;s own pattern.</li><li><strong>Extended the manifest schema to add a <code>&quot;desktop&quot;</code> platform value</strong> (<code>packages/connector-sdk</code> 0.1.0 → 0.2.0, plus Rust&#39;s <code>Platform</code> enum) rather than have desktop&#39;s store ignore <code>platforms</code> — additive, non- breaking. The two already-merged registry entries need a follow-up PR adding <code>&quot;desktop&quot;</code> to their <code>platforms</code> arrays before they&#39;ll actually appear in desktop&#39;s own store (both are plain Tier 1 HTTP calls, work identically regardless of OS).</li><li><strong>&quot;Install&quot; is exactly &quot;configure and grant,&quot; reused unchanged.</strong> Both platforms&#39; <code>grant()</code>/<code>revoke()</code> already accepted an arbitrary <code>ConnectorManifest</code> with no dependency on anything being &quot;installed&quot; first — this task&#39;s real, non-obvious cost was elsewhere: neither app had a persisted &quot;which connectors does this device have&quot; concept before this. Mobile&#39;s <code>ConnectorsScreen</code>/<code>ModelSessionProvider</code> and desktop&#39;s <code>known_connector_manifests()</code> all just rebuilt Search&#39;s manifest from its own config on the fly, since Search was the only connector that could ever exist. <code>connectors/store/installed.ts</code> (mobile) and <code>connectors/installed.rs</code> (desktop) are that persistence, the first time either — mirroring <code>grants.json</code>&#39;s own plain-JSON, fail-closed pattern, keyed by connector id, re-validated on every desktop read (<code>ConnectorManifest</code> has no derived <code>Deserialize</code>, per its own doc comment) so a manifest that no longer validates reads as &quot;not installed&quot; rather than a stale value trusted anyway.</li><li>Store screens exclude Tier 3 entries (nothing in the store could ever make one work — Tier 3 dispatches to a handler already registered inside the app) and disable install for a <code>paid</code> entry (epic 6 doesn&#39;t exist yet, so there is no working purchase path).</li><li>A found-in-passing, unrelated bug fixed while building this: desktop&#39;s <code>connectors/manifest/fixtures.rs</code> still pointed its <code>include_str!</code>s at <code>apps/mobile/src/connectors/manifest/fixtures/</code>, which task 5.1 moved to <code>packages/connector-sdk/src/fixtures/</code> months earlier without updating this reference (task 5.1 was TS-only work; desktop&#39;s own <code>cargo build</code> wasn&#39;t run as part of it). Fixed in its own commit before this task&#39;s real work started.</li></ul><p><strong>Honest gaps:</strong></p><ul><li>No &quot;update&quot; flow for an already-installed connector whose registry entry later changes shape — re-installing (same id) overwrites, but there&#39;s no notification that an update exists.</li><li>Search is a client-side substring filter over name/summary, not a real search backend — adequate for a registry with a handful of entries, not designed to scale past that.</li><li>Neither store screen was exercised through a real native Tauri window in this environment (no way to drive one directly here) — see &quot;Verified&quot; below for exactly what was and wasn&#39;t proven.</li></ul><p><strong>Verified:</strong></p><ul><li>Mobile: 258 tests pass (up from 225), including a real loopback-server test proving the fetch+parse+re-validate path against a genuine HTTP response.</li><li>Desktop: 128 Rust tests pass (up from 117, includes a real-TCP registry fetch test), 49 TS tests pass (up from 39). typecheck/lint/prettier/ offline-boundary all clean on both platforms.</li><li>A real (temporary, not committed) check confirmed <code>fetch_registry()</code> genuinely reaches <code>raw.githubusercontent.com/.../registry/ connectors.json</code> and correctly returns both real merged entries (<code>fs.sovereign.weather-open-meteo</code>, <code>fs.sovereign.github-whoami</code>).</li><li>A real desktop debug binary was built and launched (not just compiled) — started cleanly, stayed running, no panic — proving the new commands don&#39;t break app startup.</li><li>Browser-pane verification covered navigation and rendering only: Tauri&#39;s IPC bridge only exists inside a real native webview window, which this environment has no way to drive directly, so <code>invoke()</code> calls made through the Browser pane&#39;s plain-HTTP preview never resolve (confirmed: <code>ConnectorsScreen</code> shows &quot;Loading connectors…&quot; indefinitely there, exactly as expected, not a bug).</li></ul><hr><h4 id="📋-5-6-—-tier-2-sandboxed-script-runtime" tabindex="-1">📋 5.6 — Tier 2 sandboxed script runtime <a class="header-anchor" href="#📋-5-6-—-tier-2-sandboxed-script-runtime" aria-label="Permalink to &quot;📋 5.6 — Tier 2 sandboxed script runtime&quot;">​</a></h4><p><strong>Goal:</strong> Implement the sandboxed execution environment Tier 2 connectors run in.</p><p><strong>Deliverables:</strong></p><ul><li>A capability-restricted script engine (candidates: an embedded Hermes isolate, QuickJS, or WASM — choice deferred to a spike, see research 0001&#39;s open questions) with no ambient filesystem/network/device access beyond what the host explicitly injects as call parameters.</li></ul><p><strong>Dependencies:</strong> Task 5.1; blocked on a real Tier 2 use case existing (per research 0001, don&#39;t build this speculatively before something needs it).</p><p><strong>Review checklist:</strong></p><ul><li>A Tier 2 script cannot access anything — network, filesystem, other connectors&#39; credentials — beyond what was explicitly injected as its input parameters.</li></ul><h2 id="related-docs" tabindex="-1">Related Docs <a class="header-anchor" href="#related-docs" aria-label="Permalink to &quot;Related Docs&quot;">​</a></h2><ul><li><a href="./../../../CONCEPT.html">CONCEPT.md</a></li><li><a href="./../../research/0001-concept-and-connector-architecture.html">research 0001</a></li><li><a href="./../mobile/connector-framework.html">Connector Framework</a></li><li><code>confluence/concepts/plugin-development.md</code> (the <code>sovereign</code> pattern this mirrors, in the workbench repo)</li></ul>',86)])])}const m=t(i,[["render",r]]);export{u as __pageData,m as default};
